I think later we'd want to example for this as I don't find it super trivial TBH.

```js
const router = historyRouter()
const originalWrite = router.write.bind(router)
router.write = state => {
    // listening 
    originalWrite(state)
}

{
   routing: {
      router,
      stateMapping: ...
   }
}

```

What do you think of having a small example for before/after?

```js
// before
const stateMapping = {
  stateToRoute(uiState) {
    return {
      query: uiState.query,
      page: uiState.page,
      // ...
    };
  },

  routeToState(routeState) {
    return {
      query: routeState.query,
      page: routeState.page,
      // ...
    };
  },
};

// after
const stateMapping = {
  stateToRoute(uiState) {
    const indexUiState = uiState[indexName];
    return {
      query: indexUiState.query,
      page: indexUiState.page,
      // ...
    };
  },

  routeToState(routeState) {
    return {
      [indexName]: {
        query: routeState.query,
        page: routeState.page,
        // ...
      },
    };
  },
};
```
